// How a node looks in the graph view: the tile's shape and size, its glyph and the names of its ports. A port of the web app's compact
// look (tilelayout.js, glyphs.js); the table behind it (node_looks_table.inc) is generated by tools/gen-node-looks.mjs.
// All sizes are in web pixels; the caller multiplies by the UI scale.
#pragma once

#include <string>
#include <vector>

#include "imgui.h"

namespace wax::app {

enum class TileShape { Box, Rounded, Circle, Speaker, Dot };

struct NodeLookInfo {
  TileShape shape = TileShape::Box;
  std::string glyph;        // name of the picture inside the tile ("" for none)
  float sizeW = 0, sizeH = 0;   // a node that draws its own face has a fixed size (the arpeggiator's step mask); 0: compact tile
};

NodeLookInfo lookOf(const std::string& type);

// The compact tile for a node: its size, where its glyph sits and the label of each port ("" for a lone port).
struct TileLayout {
  float w = 0, h = 0;
  float glyphX = 0, glyphW = 0, glyphH = 0;   // glyphX is the glyph's centre from the tile's left edge
  std::vector<std::string> inLabels, outLabels;
};
TileLayout compactLayout(TileShape shape, const std::vector<std::string>& inputs, const std::vector<std::string>& outputs);

constexpr float kCompactRow = 14;   // the distance between ports on a tile's edge

// Draws the glyph `name` centred at `centre` (screen pixels), for a tile of this shape; scale is the UI scale.
void drawGlyph(ImDrawList* dl, const std::string& name, TileShape shape, ImVec2 centre, float scale, ImU32 ink);

}  // namespace wax::app
